  function apply(){
    if(typeof PRAYERS==="undefined") return false;
    var cur=(typeof i!=="undefined"&&i>=0)?PRAYERS[i]:null, ch=false;
    PRAYERS.forEach(function(P){
      if(!P) return;
      var hp=(P.hinweisEn&&HE[P.hinweisEn])||HD[P.id]||null; if(hp&&P.hinweisPt!==hp) P.hinweisPt=hp;
      (P.zeilen||[]).forEach(function(z){ if(!z||!z.en) return; var t=M[z.en]; if(t&&z.pt!==t){ z.pt=t; if(P===cur) ch=true; } });
    });
    return ch;
  }
